<body>
<div class="wrap">
  <h1>Szokáskövető</h1>
  <p class="sub">Jelöld be azokat a napokat, amelyeken teljesítetted a szokást – a sorozat automatikusan számolódik.</p>

  <div class="today">
    <span id="todayLabel">Mai nap</span>
    <span class="hint">A mai nap a jobb oldali menüből állítható.</span>
    <label class="sr-only" for="todaySel">Mai nap kiválasztása</label>
    <select id="todaySel" aria-label="Mai nap"></select>
  </div>

  <div id="list"></div>

  <form class="add" id="addForm">
    <label class="sr-only" for="habitInput">Új szokás neve</label>
    <input id="habitInput" type="text" maxlength="40" placeholder="Pl. 20 perc séta" autocomplete="off">
    <button type="submit">Hozzáadás</button>
  </form>

  <p class="sr-only" id="live" aria-live="polite"></p>
</div>

<script>
(function () {
  const DOW = ['H','K','Sze','Cs','P','Szo','V'];
  const DOW_FULL = ['hétfő','kedd','szerda','csütörtök','péntek','szombat','vasárnap'];
  const KEY = 'habit-tracker-v1';

  const listEl = document.getElementById('list');
  const form = document.getElementById('addForm');
  const input = document.getElementById('habitInput');
  const todaySel = document.getElementById('todaySel');
  const todayLabel = document.getElementById('todayLabel');
  const live = document.getElementById('live');

  let habits = [];
  let todayIndex = (new Date().getDay() + 6) % 7; // 0 = hétfő
  let pendingDelete = null;

  function isoWeekday() { return (new Date().getDay() + 6) % 7; }
  function weekKey() {
    const d = new Date();
    const wd = isoWeekday();
    const mon = new Date(d.getFullYear(), d.getMonth(), d.getDate() - wd);
    return mon.getFullYear() + '-' + (mon.getMonth() + 1) + '-' + mon.getDate();
  }
  function defaultState() {
    return { week: weekKey(), habits: [
      { id: 'h1', name: '20 perc séta', days: [true,true,false,false,false,false,false] },
      { id: 'h2', name: '8 óra alvás', days: [true,true,true,false,false,false,false] },
      { id: 'h3', name: 'Vízivás 2L', days: [true,false,true,true,false,false,false] },
      { id: 'h4', name: 'Olvasás 15 perc', days: [false,true,true,true,true,false,false] },
      { id: 'h5', name: 'Nyújtás', days: [true,true,false,false,false,false,false] }
    ] };
  }
  function load() {
    if (window.alfy && window.alfy.storage) {
      return window.alfy.storage.get(KEY).then(v => {
        if (v && Array.isArray(v.habits)) { habits = v.habits; todayIndex = isoWeekday(); return; }
        habits = defaultState().habits;
      }).catch(() => { habits = defaultState().habits; });
    }
    habits = defaultState().habits;
    return Promise.resolve();
  }
  function save() {
    if (window.alfy && window.alfy.storage) window.alfy.storage.set(KEY, { week: weekKey(), habits: habits });
  }
  function announce(msg) { live.textContent = ''; setTimeout(() => { live.textContent = msg; }, 30); }

  function currentStreak(days) {
    if (days[todayIndex]) {
      let s = 0;
      for (let i = todayIndex; i >= 0; i--) { if (days[i]) s++; else break; }
      return s;
    }
    return 0;
  }

  function render() {
    listEl.innerHTML = '';
    if (habits.length === 0) {
      const e = document.createElement('div');
      e.className = 'empty';
      e.innerHTML = '<div class="big">✦</div><p>Még nincs szokásod. Írd be az első szokást, majd jelöld be a teljesített napokat.</p>';
      listEl.appendChild(e);
    }
    habits.forEach(h => {
      const card = document.createElement('section');
      card.className = 'card';
      const streak = currentStreak(h.days);

      const head = document.createElement('div');
      head.className = 'card-head';
      const name = document.createElement('h2');
      name.className = 'habit-name';
      name.textContent = h.name;
      const st = document.createElement('span');
      st.className = 'streak' + (streak > 0 ? '' : ' off');
      st.innerHTML = '<span class="dot"></span>' + (streak > 0 ? streak + ' napos sorozat' : 'nincs sorozat');
      head.appendChild(name);
      head.appendChild(st);

      const days = document.createElement('div');
      days.className = 'days';
      for (let i = 0; i < 7; i++) {
        const b = document.createElement('button');
        b.type = 'button';
        b.className = 'day' + (i === todayIndex ? ' is-today' : '');
        b.setAttribute('aria-pressed', h.days[i] ? 'true' : 'false');
        b.setAttribute('aria-label', h.name + ' – ' + DOW_FULL[i] + (i === todayIndex ? ' (ma)' : '') + (h.days[i] ? ', teljesítve' : ', nem teljesítve'));
        const dow = document.createElement('span');
        dow.className = 'dow';
        dow.textContent = DOW[i];
        const box = document.createElement('span');
        box.className = 'box';
        box.textContent = h.days[i] ? '✓' : '';
        b.appendChild(dow);
        b.appendChild(box);
        b.addEventListener('click', () => toggle(h.id, i));
        days.appendChild(b);
      }

      card.appendChild(head);
      card.appendChild(days);

      if (pendingDelete === h.id) {
        const conf = document.createElement('div');
        conf.className = 'confirm';
        conf.innerHTML = '<span>Törlöd a(z) „' + escapeHtml(h.name) + '” szokást?</span>';
        const yes = document.createElement('button');
        yes.type = 'button'; yes.className = 'yes'; yes.textContent = 'Törlés';
        yes.addEventListener('click', () => { habits = habits.filter(x => x.id !== h.id); pendingDelete = null; save(); render(); announce('Szokás törölve.'); });
        const no = document.createElement('button');
        no.type = 'button'; no.textContent = 'Mégse';
        no.addEventListener('click', () => { pendingDelete = null; render(); });
        conf.appendChild(yes); conf.appendChild(no);
        card.appendChild(conf);
      } else {
        const del = document.createElement('button');
        del.type = 'button'; del.className = 'confirm';
        del.style.border = 'none'; del.style.background = 'none'; del.style.color = 'var(--text-muted)';
        del.style.padding = '8px 0 0'; del.style.cursor = 'pointer'; del.style.font = 'inherit';
        del.textContent = 'Törlés';
        del.addEventListener('click', () => { pendingDelete = h.id; render(); });
        card.appendChild(del);
      }

      listEl.appendChild(card);
    });
  }

  function escapeHtml(s) { return s.replace(/[&<>"']/g, c => ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' }[c])); }

  function toggle(id, i) {
    const h = habits.find(x => x.id === id);
    if (!h) return;
    h.days[i] = !h.days[i];
    save(); render();
    const st = currentStreak(h.days);
    announce(h.name + ': ' + DOW_FULL[i] + (h.days[i] ? ' bejelölve.' : ' törölve.') + (st > 0 ? ' Sorozat: ' + st + ' nap.' : ' Nincs sorozat.'));
  }

  form.addEventListener('submit', e => {
    e.preventDefault();
    const name = input.value.trim();
    if (!name) { announce('Írj be egy szokásnevet.'); input.focus(); return; }
    habits.push({ id: 'h' + Date.now() + Math.floor(Math.random() * 1000), name: name, days: [false,false,false,false,false,false,false] });
    input.value = '';
    save(); render();
    announce('„' + name + '” hozzáadva.');
    input.focus();
  });

  function initToday() {
    for (let i = 0; i < 7; i++) {
      const o = document.createElement('option');
      o.value = String(i);
      o.textContent = DOW_FULL[i];
      todaySel.appendChild(o);
    }
    todaySel.value = String(todayIndex);
    todayLabel.textContent = 'Ma: ' + DOW_FULL[todayIndex];
    todaySel.addEventListener('change', () => {
      todayIndex = Number(todaySel.value);
      todayLabel.textContent = 'Ma: ' + DOW_FULL[todayIndex];
      render();
      announce('Mai nap: ' + DOW_FULL[todayIndex]);
    });
  }

  initToday();
  load().then(render);
})();
</script>
</body>
</html>
